export function projectileReadabilityContrastPresentation(input, reducedFlash = false) { const crowd = clamp01(input.crowd), gap = (input.critical ? .18 : .12) + (input.bossActive ? .03 : 0) + crowd * .02, body = clamp01(Math.max(input.bodyFloor, (input.critical ? .58 : .4) + crowd * .025) * (reducedFlash ? .98 : 1)), contour = projectileContourOwnershipPresentation({ critical: input.critical, bossActive: input.bossActive, overlap: crowd }, reducedFlash), dense = denseEdgeFamilyPresentation({ family: 'projectile', crowd, critical: input.critical, bossProtected: input.bossActive, safeLaneVisible: false }, false, reducedFlash); return { bodyAlphaFloor: body, trailScale: Math.min(clamp01(input.trailScale), Math.max(.42, 1 - gap - crowd * .12)) * contour.secondaryContourScale * dense.secondaryContourScale, minimumGap: gap, presentationOnly: true }; }
