export function hazardReadabilityContrastPresentation(input, reducedFlash = false) { const crowd = clamp01(input.crowd), gap = (input.telegraph ? .15 : .1) + (input.critical ? .04 : 0) + crowd * .02, edge = clamp01(Math.max(input.edgeFloor, (input.telegraph ? .48 : .3) + (input.critical ? .04 : 0)) * (reducedFlash ? .97 : 1)), contour = hazardContourOwnershipPresentation({ telegraph: input.telegraph, critical: input.critical, overlap: crowd }, reducedFlash), dense = denseEdgeFamilyPresentation({ family: 'hazard', crowd, critical: input.critical, bossProtected: input.telegraph, safeLaneVisible: false }, false, reducedFlash); return { edgeAlphaFloor: edge, fillScale: Math.min(clamp01(input.fillScale), Math.max(.36, 1 - gap - crowd * .16)) * contour.secondaryContourScale * dense.secondaryContourScale, minimumGap: gap, presentationOnly: true }; }
export function safeLaneReadabilityContrastPresentation(input, reducedFlash = false) { const confidence = clamp01(input.confidence), crowd = clamp01(input.crowd), path = clamp01(Math.max(input.pathFloor, .58 + confidence * .14 + (input.critical ? .06 : 0) + (input.bossActive ? .03 : 0)) * (reducedFlash ? .98 : 1)), contour = safeLaneContourOwnershipPresentation({ visible: true, confidence, overlap: crowd }, reducedFlash), dense = denseEdgeFamilyPresentation({ family: 'safeLane', crowd, critical: input.critical, bossProtected: input.bossActive, safeLaneVisible: true }, false, reducedFlash); return { pathAlphaFloor: path, decorativeScale: Math.max(.5, 1 - crowd * .32 - (input.critical ? .08 : 0)) * contour.secondaryContourScale * dense.secondaryContourScale, presentationOnly: true }; }
