export function readabilityContrastBudgetPresentation(input, reducedMotion = false, reducedFlash = false) { const critical = clamp01(Math.max(0, input.criticalCount) / 3), crowd = clamp01(input.crowd), stress = clamp01(crowd * .78 + critical * .22 + (input.bossActive ? .05 : 0)), contour = contourOwnershipBudgetPresentation(input, reducedMotion, reducedFlash), dense = denseEdgeBudgetPresentation(input, reducedMotion, reducedFlash); return { stress, primaryScale: 1, secondaryScale: Math.max(.46, 1 - stress * .4) * (reducedMotion ? .97 : 1) * (reducedFlash ? .96 : 1) * contour.secondaryContourScale * dense.secondaryContourScale, safeLaneScale: input.safeLaneVisible ? 1 + stress * .035 * (reducedFlash ? .9 : 1) : 1, presentationOnly: true }; }
